import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.DnrXFDHb.js";const g=JSON.parse('{"title":"电改2.0：中国电力市场化进度全景地图（2026）","description":"各省电力现货市场进度差3-5年——对算电协同布局意味着什么","frontmatter":{"title":"电改2.0：中国电力市场化进度全景地图（2026）","pubDate":"2026-06-24T00:00:00.000Z","description":"各省电力现货市场进度差3-5年——对算电协同布局意味着什么","tags":["电改","电力现货市场","电价","算电协同"],"visibility":"public"},"headers":[],"relativePath":"电改2.0进度地图_网站深度版.md","filePath":"电改2.0进度地图_网站深度版.md","lastUpdated":null}'),h={name:"电改2.0进度地图_网站深度版.md"};function e(n,t,l,i,s,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="同一度电-三个世界" tabindex="-1">同一度电，三个世界 <a class="header-anchor" href="#同一度电-三个世界" aria-label="Permalink to &quot;同一度电，三个世界&quot;">​</a></h2><p>甘肃现货市场午间电价一度低至 0.145 元/度。同一周，广东现货均价约 460 元/MWh（0.46 元/度），山西约 260 元/MWh（0.26 元/度）。</p><p>同一商品，三倍价差。这不是市场分割，而是电力现货市场建设进度的时间差。</p><p>截至 2026 年 6 月，全国已有 7 省电力现货市场正式运行，5 省进入连续结算试运行（年内转正），但仍有近 10 省停留在短周期试运行或未启动。这个进度梯度，直接创造了跨省套利空间和选址决策梯度。</p><p>对算电协同投资者来说，选对省份比选对技术路线重要得多。</p><hr><h2 id="一、四省分层进度地图" tabindex="-1">一、四省分层进度地图 <a class="header-anchor" href="#一、四省分层进度地图" aria-label="Permalink to &quot;一、四省分层进度地图&quot;">​</a></h2><p>我们将各省电力现货市场建设进度分为四个梯队。分化的核心标准是：是否已从&quot;试运行&quot;转为&quot;正式运行&quot;——前者意味着规则还在迭代，后者意味着市场机制基本定型。</p><h3 id="第一梯队-正式运行-7省" tabindex="-1">第一梯队：正式运行（7省） <a class="header-anchor" href="#第一梯队-正式运行-7省" aria-label="Permalink to &quot;第一梯队：正式运行（7省）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>省份</th><th>转正时间</th><th>2026年6月第3周均价</th><th>核心特征</th><th>算电协同价值</th></tr></thead><tbody><tr><td><strong>山西</strong></td><td>2023年底</td><td>日前 265.55，实时 305.34 元/MWh</td><td>首批试点，规则迭代至 V15.0，运行最成熟</td><td>⭐⭐⭐ 辅助服务市场成熟，储能+数据中心 VPP 可参与</td></tr><tr><td><strong>广东</strong></td><td>2024年6月</td><td>日前~460，实时~477 元/MWh</td><td>负荷最大，电价最高，2026年容量电价气电涨 164%-296%</td><td>⭐⭐⭐ VPP 首单已落地，但电价高不利绿电直供</td></tr><tr><td><strong>山东</strong></td><td>2024年6月</td><td>日前 303-460，实时 235-436 元/MWh</td><td>新能源渗透率高，独立储能容量补偿持续退坡</td><td>⭐⭐ 新能源+储能组合有套利空间</td></tr><tr><td><strong>甘肃</strong></td><td>2024年9月</td><td>午间地板价常态化（曾低至 0.145 元/度）</td><td>新能源占比最高，电价全国最低之一</td><td>⭐⭐⭐⭐⭐ 算电协同首选地，绿电成本确定性优势</td></tr><tr><td><strong>蒙西</strong></td><td>2025年2月</td><td>实时加权 147-331，均价~276 元/MWh</td><td>首个非试点转正，内蒙古数据中心集群所在地</td><td>⭐⭐⭐⭐⭐ 最优布局地：低电价 + 集群 + 绿电直连政策</td></tr><tr><td><strong>湖北</strong></td><td>2025年6月</td><td>数据覆盖中</td><td>中部电力枢纽，初步市场化</td><td>⭐⭐ 区位价值中等</td></tr><tr><td><strong>浙江</strong></td><td>2025年底</td><td>数据覆盖中</td><td>高负荷省份，电价偏高</td><td>⭐⭐ 算力需求大但电价高</td></tr></tbody></table><p>这 7 省构成了中国电力市场化的一线阵营。其中蒙西和甘肃是我们认为算电协同价值最高的两个省份——原因不仅是电价低，更在于政策和基础设施配套的成熟度。</p><h3 id="第二梯队-连续结算试运行-年内转正" tabindex="-1">第二梯队：连续结算试运行（年内转正） <a class="header-anchor" href="#第二梯队-连续结算试运行-年内转正" aria-label="Permalink to &quot;第二梯队：连续结算试运行（年内转正）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>省份</th><th>当前状态</th><th>预计转正</th><th>6月第3周均价</th><th>关键观察</th></tr></thead><tbody><tr><td><strong>安徽</strong></td><td>连续试运行</td><td>2026年6月底</td><td>日前 177-298，实时 155-315 元/MWh</td><td>元旦出现市场力干预，规则仍在磨合</td></tr><tr><td><strong>陕西</strong></td><td>连续试运行</td><td>2026年6月底</td><td>日前 66-313，实时 70-303 元/MWh</td><td>地板价常态化，30-70 元/MWh 频现</td></tr><tr><td><strong>辽宁</strong></td><td>2025年3月启动</td><td>2026年Q3-Q4</td><td>日前 112-324，实时 106-357 元/MWh</td><td>2026年引入负电价（-100 元/MWh 下限），规则激进</td></tr><tr><td><strong>河北南网</strong></td><td>2025年3月启动</td><td>2026年</td><td>数据待补充</td><td>承接北京外溢算力需求，关注度高</td></tr><tr><td><strong>南方区域市场</strong></td><td>2025年6月启动</td><td>2026年Q4</td><td>首个跨省区域市场</td><td>广东+广西+云南+贵州+海南，意义大于直接收益</td></tr></tbody></table><p>第二梯队的核心看点是转正窗口。安徽和陕西可能在 2026 年 6 月底转正，届时将有 9 省正式运行。区域市场（南方区域）的开创性在于跨省融合——虽然短期不产生套利空间，但长期重构省间交易格局。</p><h3 id="第三梯队-长周期试运行" tabindex="-1">第三梯队：长周期试运行 <a class="header-anchor" href="#第三梯队-长周期试运行" aria-label="Permalink to &quot;第三梯队：长周期试运行&quot;">​</a></h3><p>福建、四川、江苏、湖南、河南、宁夏、重庆、上海、吉林——共 9 省（市）。</p><p><strong>关键观察</strong>：江苏日前均价约 370 元/MWh，电价偏高且稳定，工业负荷支撑强，但尚未转正意味着市场化参与仍受限。四川受水电影响，丰枯季节电价波动巨大，存在独特的季节性套利机会。</p><h3 id="第四梯队-短周期试运行或未启动" tabindex="-1">第四梯队：短周期试运行或未启动 <a class="header-anchor" href="#第四梯队-短周期试运行或未启动" aria-label="Permalink to &quot;第四梯队：短周期试运行或未启动&quot;">​</a></h3><p>江西、黑龙江、新疆、蒙东、青海——共 5 省（区）。</p><p><strong>核心矛盾</strong>：黑龙江是典型的&quot;电改落后省&quot;，但电价极低。若未来转正，存在制度性红利——只是这个&quot;未来&quot;可能是 3 年后。</p><hr><h2 id="二、八省价格分化-6月第3周全景" tabindex="-1">二、八省价格分化：6月第3周全景 <a class="header-anchor" href="#二、八省价格分化-6月第3周全景" aria-label="Permalink to &quot;二、八省价格分化：6月第3周全景&quot;">​</a></h2><p>我们整理了 2026 年 6 月 15 日至 21 日八省现货市场价格数据。这是手头能拿到的最近一期可比数据。</p><table tabindex="0"><thead><tr><th>省份</th><th>日前最低</th><th>日前最高</th><th>实时最低</th><th>实时最高</th><th>平均中枢</th><th>波动特征</th></tr></thead><tbody><tr><td>广东</td><td>135.71</td><td>477.76</td><td>128.45</td><td>536.98</td><td>~460</td><td>峰谷价差极大，实时波动剧烈</td></tr><tr><td>山西</td><td>205.28</td><td>318.19</td><td>191.46</td><td>334.56</td><td>~260</td><td>相对平稳，市场成熟</td></tr><tr><td>山东</td><td>303.55</td><td>460.36</td><td>235.69</td><td>436.53</td><td>~350</td><td>新能源出力日波动大</td></tr><tr><td>蒙西</td><td>188.24</td><td>276.38</td><td>188.24</td><td>276.38</td><td>~240</td><td>发电侧加权低，用户侧加权高</td></tr><tr><td>陕西</td><td>66.38</td><td>313.63</td><td>82.08</td><td>303.97</td><td>~150</td><td>地板价频现，西北低电价特征</td></tr><tr><td>辽宁</td><td>112.60</td><td>324.79</td><td>106.77</td><td>357.37</td><td>~200</td><td>负电价常态化，2026新规效应</td></tr><tr><td>江苏</td><td>325.22</td><td>369.63</td><td>333.73</td><td>380.05</td><td>~350</td><td>高且稳定，工业负荷支撑</td></tr><tr><td>安徽</td><td>177.07</td><td>298.55</td><td>155.62</td><td>315.12</td><td>~250</td><td>试运行中，市场力干预后趋稳</td></tr></tbody></table><p>数据来源：北极星电力市场网周报 2026.6.15-6.21，单位元/MWh，广东为厘/kWh 换算。</p><p>两个核心发现：</p><p><strong>第一，电价梯度就是选址梯度。</strong> 蒙西均价 240 元/MWh vs 广东 460 元/MWh，价差接近一倍。对数据中心这类 7×24 小时高负荷用户，年电费差异以亿计。一个 100MW 的数据中心，在蒙西比在广东每年省电费约 1.9 亿元（假设 70% 负载率）。</p><p><strong>第二，时点套利空间同样可观。</strong> 陕西日前最低 66 元 vs 最高 313 元，日内价差 4.7 倍。这对配置储能的用户是天然套利信号——只是需要现货市场已正式运行才能落地。</p><hr><h2 id="三、2026年三大规则变化" tabindex="-1">三、2026年三大规则变化 <a class="header-anchor" href="#三、2026年三大规则变化" aria-label="Permalink to &quot;三、2026年三大规则变化&quot;">​</a></h2><h3 id="_3-1-负电价正式化" tabindex="-1">3.1 负电价正式化 <a class="header-anchor" href="#_3-1-负电价正式化" aria-label="Permalink to &quot;3.1 负电价正式化&quot;">​</a></h3><p>辽宁 2026 年交易规则正式引入 -100 元/MWh 的价格下限。这是国内首个在正式规则中明确负电价下限的省份。我们认为这不是孤例——随着新能源渗透率持续提升（甘肃、山东、蒙西午间出力过剩已是常态），更多新能源大省将会跟进。</p><p><strong>影响</strong>：负电价常态化直接利好储能和灵活负荷。对数据中心而言，若能在负电价时段增加负荷（如训练任务调度），可实现&quot;用电赚钱&quot;。</p><h3 id="_3-2-容量电价加速分化" tabindex="-1">3.2 容量电价加速分化 <a class="header-anchor" href="#_3-2-容量电价加速分化" aria-label="Permalink to &quot;3.2 容量电价加速分化&quot;">​</a></h3><p>广东 2026 年容量电价调整幅度惊人：气电涨 164%-296%，煤电涨 65%。但同时，独立储能容量补偿持续退坡。</p><p>两个信号：一是气电的价值在电力系统中被重新定价（调峰价值）；二是储能的容量补偿红利窗口正在收窄，储能投资的收益预期正在从&quot;政策补贴&quot;转向&quot;现货套利&quot;。</p><h3 id="_3-3-新能源全面入市" tabindex="-1">3.3 新能源全面入市 <a class="header-anchor" href="#_3-3-新能源全面入市" aria-label="Permalink to &quot;3.3 新能源全面入市&quot;">​</a></h3><p>136 号文推动存量集中式新能源 30%-50% 电量入市，分布式光伏逐步全量入市。</p><p>这是一个分水岭时刻。新能源从&quot;保量保价&quot;走向&quot;市场竞争&quot;，意味着一件事：<strong>电价波动性将系统性上升</strong>。对算电协同来说，电价波动=套利空间扩大=储能+VPP+AI 调度的价值上升。但对缺乏风险管理能力的新能源资产持有者来说，收入不确定性大幅增加。</p><hr><h2 id="四、投资含义矩阵" tabindex="-1">四、投资含义矩阵 <a class="header-anchor" href="#四、投资含义矩阵" aria-label="Permalink to &quot;四、投资含义矩阵&quot;">​</a></h2><p>基于以上分析，我们构建了一个省份×角色的选择矩阵。</p><table tabindex="0"><thead><tr><th>省域</th><th>市场成熟度</th><th>电价水平</th><th>适合角色</th><th>推荐优先级</th></tr></thead><tbody><tr><td>蒙西</td><td>★★★★★</td><td>低(~240)</td><td>数据中心绿电直供</td><td><strong>P0</strong></td></tr><tr><td>甘肃</td><td>★★★★★</td><td>极低(~150)</td><td>算力西部枢纽</td><td><strong>P0</strong></td></tr><tr><td>山西</td><td>★★★★★</td><td>中低(~260)</td><td>辅助服务+储能套利</td><td>P1</td></tr><tr><td>陕西</td><td>★★★★</td><td>低(~150)</td><td>绿电直供（关注转正窗口）</td><td>P1</td></tr><tr><td>广东</td><td>★★★★★</td><td>高(~460)</td><td>VPP聚合/需求响应</td><td>P1（不同策略）</td></tr><tr><td>辽宁</td><td>★★★★</td><td>中低(~200)</td><td>绿电+储能组合，负电价套利</td><td>P2</td></tr><tr><td>江苏</td><td>★★★</td><td>高(~350)</td><td>暂不适合，等转正后看</td><td>P3</td></tr><tr><td>山东</td><td>★★★★★</td><td>中(~350)</td><td>新能源+储能组合套利</td><td>P2</td></tr></tbody></table><p>我们对&quot;P0&quot;的定义是：<strong>现在就可以推进布局，不需要等待政策落地或市场成熟。</strong></p><p>蒙西的优势是多重叠加的——内蒙古数据中心集群已是国家级战略，绿电直连政策（688 号文）框架明确，现货市场已正式运行，电价在 240 元/MWh 水平稳定。这些条件同时满足的省份，目前只有蒙西。</p><p>甘肃的核心价值是电价确定性。当全国大多数省份电价随燃料成本和碳排放成本上升时，甘肃的新能源高渗透率提供了一个天然的&quot;电价锚&quot;——午间低价是结构性的，不是周期性的。</p><h3 id="四大赛道主题" tabindex="-1">四大赛道主题 <a class="header-anchor" href="#四大赛道主题" aria-label="Permalink to &quot;四大赛道主题&quot;">​</a></h3><p>除了选址决策，我们也在关注四个跨省投资主题：</p><ol><li><p><strong>电力交易 AI/软件</strong>：现货市场扩容直接增加交易频次。一个省级现货市场每天有 96 个出清点（15 分钟间隔），AI 报价策略和风险管理的需求正在从&quot;可选&quot;变成&quot;必须&quot;。国能日新、清大科越这类服务商的商业模式在电改进程中受益。</p></li><li><p><strong>虚拟电厂聚合商</strong>：广东 33MW VPP 已入市，这是国内首个商业化 VPP 案例。电改进度越快的省份，VPP 的价值越大——因为现货市场提供了 VPP 聚合分布式资源的定价基础。</p></li><li><p><strong>绿电直供项目</strong>：688 号文明确支持数据中心负荷绿电直连。内蒙古已发布执行细则。这是我们认为 P0 级别机会的核心原因——不是概念，是已有政策框架+市场工具的项目级机会。</p></li><li><p><strong>储能套利</strong>：山西已经跑通储能现货套利模式。随着更多省份转正和负电价机制的引入，储能套利空间正在从&quot;一个省的故事&quot;变成&quot;多个省的实践&quot;。</p></li></ol><hr><h2 id="五、风险因素-观点-非事实" tabindex="-1">五、风险因素（观点，非事实） <a class="header-anchor" href="#五、风险因素-观点-非事实" aria-label="Permalink to &quot;五、风险因素（观点，非事实）&quot;">​</a></h2><p>以下是我们认为需要持续跟踪的风险，标注为<strong>我们的判断</strong>而非已确认的事实：</p><ol><li><p><strong>省间壁垒仍存</strong>：各省规则差异大，实际落地有地方保护。跨省交易的输电通道占用费尚未明确。<strong>我们的判断</strong>：2-3 年内，省级市场仍是主战场，跨省交易以补充为主。</p></li><li><p><strong>容量电价政策碎片化</strong>：广东涨了，但其他省未必跟进。全国统一的容量市场框架尚未出台。<strong>我们的判断</strong>：2027 年前不太可能统一，各省容量电价的差异化本身就是套利来源。</p></li><li><p><strong>新能源入市节奏不确定</strong>：存量项目补贴退坡的节奏各省不同，部分项目可能面临收入悬崖。<strong>我们的判断</strong>：对有竞争力（低 LCOE）的新项目是利好（市场化定价可能高于补贴），但对高成本存量项目是风险。</p></li><li><p><strong>监管干预风险</strong>：安徽 2026 年元旦出现市场力干预，湖北多次触发缓解机制。<strong>我们的判断</strong>：监管干预短期内是常态。规则磨合期的市场存在&quot;政策市&quot;特征。</p></li><li><p><strong>输电通道占用费未明确</strong>：这是影响跨省绿电直供给的最关键变量。<strong>我们的判断</strong>：内蒙古 688 号文框架下，过网费可能在 0.02-0.05 元/kWh 水平——如果低于 0.03 元，算电协同的经济学完全成立。</p></li></ol><hr><h2 id="六、下一步需要验证的关键假设" tabindex="-1">六、下一步需要验证的关键假设 <a class="header-anchor" href="#六、下一步需要验证的关键假设" aria-label="Permalink to &quot;六、下一步需要验证的关键假设&quot;">​</a></h2><p>以下是我们在 2026 年下半年重点验证的问题，供读者与我们一起跟踪：</p><ol><li>蒙西/甘肃数据中心实际绿电采购成本 vs 目录电价 vs 现货均价——量化&quot;到底能省多少&quot;</li><li>各省虚拟电厂注册流程和准入门槛差异——哪些省真正对第三方聚合商开放</li><li>内蒙古&quot;数据中心负荷绿电直连&quot;的过网费细则</li><li>负电价机制是否会从辽宁扩展到山东/甘肃/蒙西</li><li>南方区域市场运行后的跨省价差变化</li></ol><hr><h2 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to &quot;核心结论&quot;">​</a></h2><p>电力市场化不是一个&quot;yes or no&quot;的问题，而是一个&quot;where and when&quot;的问题。</p><p>7 省正式运行、5 省即将转正、14 省在建设中——这个进度梯度本身就是最大的投资信号。对算电协同来说，选对省份 = 50% 的工作。蒙西和甘肃现在是确定性最高的选择，不是因为是唯一对的，而是因为时间成本最低。</p><p>我们会在下半年持续更新这份进度地图。下一版将加入更多省的实际电价数据和绿电采购成本对比。</p><hr><h2 id="数据来源与引用" tabindex="-1">数据来源与引用 <a class="header-anchor" href="#数据来源与引用" aria-label="Permalink to &quot;数据来源与引用&quot;">​</a></h2><ol><li>北极星电力市场网：2026年6月第3周（6.15-6.21）八省现货价格周报</li><li>北极星电力市场网：2026年5月第1-2周现货价格周报</li><li>数字储能网：2026开年24省区现货价格涨跌观察（2026.1.26）</li><li>RMI 落基山研究所：《2025 电力市场化改革与电价体系洞察》</li><li>广东电力交易中心：《广东电力市场 2026 年交易关键机制和参数》（2025.10）</li><li>国办发 688 号文：数据中心绿电直连政策框架</li><li>国办发 136 号文：新能源全面入市政策</li></ol><hr><p><em>本文为独立研究观点，不构成投资建议。数据截至 2026 年 6 月 24 日。</em></p>',67)])])}const q=d(h,[["render",e]]);export{g as __pageData,q as default};
